        readonly 'failure.prompt.title': '请帮我找出这次 DSH 皮肤操作失败的原因。先只读诊断，区分已验证事实和推断，不预先保证能修复。';
        readonly 'failure.prompt.hostDesktop': 'Desktop 版本以应用“关于”为准，不能用终端 npm dsh 版本代替。如果当前宿主提供插件管理工具（plugin_manager），修复后可由 Agent 在你确认精确目标和 profile 后重试安装；否则在官方插件页操作。安装、启用、停用及重启仍以你的确认/操作为准；不要执行 dsh plugin --profile desktop，不用 npm/pnpm 直接写 Desktop profile，不替换 profile。';
        readonly 'failure.prompt.hostWeb': '核对正在服务当前页面的 Web DSH 版本，不能用另一个 CLI 安装代替。包操作优先走同一 DSH 的官方管理能力，重试原操作；不要把停用、卸载或取消常驻改成安装。';
        readonly 'failure.prompt.header': '- DSH：{host}；页面报告版本：{version}\n- 原操作：{action}（{kind}）；请求目标 skin id：{skinId}\n- 待排查皮肤：{skinZh} / {skinEn}\n- skin id：{skinIdValue}；package：{packageName}；loader rowId：{rowId}\n- 仓库：{repo}\n- 目录版本：{catalogVersion}；commit：{commit}\n- 目录安装目标：{target}（实际安装来源需要另行确认）\n- 本次目标：{goal}\n- 排查类别：{topic}';
        readonly 'failure.prompt.factCheck': '先从实际进程、应用与运行时确认 DSH home、profile 和加载来源，不猜测默认 ~/.dsh。{instructions}';
        readonly 'failure.prompt.safety': '不要读取 .env、凭据或其他存放秘密的配置。混合配置若可能含秘密，先说明文件与所需的目标字段，取得限定读取授权后仅提取这些字段，不输出整份配置、完整进程参数或无关插件设置。不要改变安全策略、放宽 allowBuild、关闭新包保护、跳过完整性校验、删除整个锁文件或修改其他皮肤。';
        readonly 'failure.prompt.globalSettings': '涉及全局或启动设置时，先展示准确文件、行、键和值及最小改动，取得我确认并备份；保留注释与无关字段。若你运行在被修复的同一个 DSH 中，不要改写自己的活动组合配置、安装或卸载当前 DSH、停止或重启自己；先准备可重复执行的 apply 与 rollback 方案，列出前置条件和校验，由外部终端或独立 agent 在退出相关 DSH 后执行。无权限、来源不唯一、动态或远程配置时说明具体缺少什么，交由原管理工具处理。';
        readonly 'failure.prompt.finish': '修复后按原操作重试并遵守官方批准流程；运行时结果未确认前不重复发起包操作。核对实际安装版本、启用/停用选择、enabled 和 fiber 状态，按 DSH 提示由我重启。不能把已安装当成已启用，也不能把 application: applied 当成代码已加载；读不到运行状态就请我提供官方页面结果并注明尚未验证。';
